#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 hlslcc_mtx4x4unity_ObjectToWorld[4];
uniform 	vec4 hlslcc_mtx4x4unity_MatrixVP[4];
uniform 	mediump vec4 _Color;
in highp vec4 in_POSITION0;
in highp vec2 in_TEXCOORD0;
in mediump vec4 in_COLOR0;
out highp vec2 vs_TEXCOORD0;
out highp float vs_TEXCOORD1;
out mediump vec4 vs_COLOR0;
vec4 u_xlat0;
vec4 u_xlat1;
void main()
{
    u_xlat0 = in_POSITION0.yyyy * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[2] * in_POSITION0.zzzz + u_xlat0;
    u_xlat0 = u_xlat0 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat1;
    gl_Position = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat0.wwww + u_xlat1;
    u_xlat0.x = dot(hlslcc_mtx4x4unity_ObjectToWorld[3].xy, vec2(12.9898005, 78.2330017));
    u_xlat0.x = sin(u_xlat0.x);
    u_xlat0.x = u_xlat0.x * 43758.5469;
    vs_TEXCOORD1 = fract(u_xlat0.x);
    vs_TEXCOORD0.xy = in_TEXCOORD0.xy;
    vs_COLOR0 = in_COLOR0 * _Color;
    return;
}


#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 _Time;
uniform 	float _WaveStrength;
uniform 	float _WaveScale;
uniform 	float _WaveSpeed;
uniform 	float _Randomness;
uniform 	float _VerticalStrength;
UNITY_LOCATION(0) uniform mediump sampler2D _MainTex;
in highp  vec2 vs_TEXCOORD0;
in highp  float vs_TEXCOORD1;
in mediump  vec4 vs_COLOR0;
layout(location = 0) out mediump vec4 SV_Target0;
vec4 u_xlat0;
mediump vec4 u_xlat16_0;
vec4 u_xlat1;
vec2 u_xlat2;
float u_xlat3;
float u_xlat4;
float u_xlat5;
void main()
{
    u_xlat0.x = _Time.y * _WaveSpeed;
    u_xlat2.x = vs_TEXCOORD0.y * _WaveScale + u_xlat0.x;
    u_xlat2.x = vs_TEXCOORD1 * 10.0 + u_xlat2.x;
    u_xlat4 = vs_TEXCOORD0.y * _WaveScale;
    u_xlat1 = u_xlat0.xxxx * vec4(1.30999994, 0.569999993, 1.70000005, 0.310000002);
    u_xlat0.xw = u_xlat0.xx * vec2(0.829999983, 0.460000008);
    u_xlat1.xz = vec2(u_xlat4) * vec2(1.73000002, 2.30999994) + (-u_xlat1.xz);
    u_xlat4 = u_xlat4 * 0.629999995 + u_xlat1.y;
    u_xlat3 = vs_TEXCOORD0.y * 7.36999989 + u_xlat1.w;
    u_xlat3 = vs_TEXCOORD1 * 10.0 + u_xlat3;
    u_xlat3 = sin(u_xlat3);
    u_xlat3 = u_xlat3 * 0.5 + 0.5;
    u_xlat3 = u_xlat3 * 0.599999964 + 0.699999988;
    u_xlat4 = (-vs_TEXCOORD0.x) * 4.69999981 + u_xlat4;
    u_xlat2.y = vs_TEXCOORD1 * 37.0 + u_xlat4;
    u_xlat2.xy = sin(u_xlat2.xy);
    u_xlat1.x = vs_TEXCOORD0.x * 2.29999995 + u_xlat1.x;
    u_xlat5 = vs_TEXCOORD0.x * 7.0 + u_xlat1.z;
    u_xlat1.z = vs_TEXCOORD1 * 52.0 + u_xlat5;
    u_xlat1.x = vs_TEXCOORD1 * 21.0 + u_xlat1.x;
    u_xlat1.xz = sin(u_xlat1.xz);
    u_xlat1.x = u_xlat1.x * 0.280000001;
    u_xlat2.x = u_xlat2.x * 0.449999988 + u_xlat1.x;
    u_xlat2.x = u_xlat2.y * 0.180000007 + u_xlat2.x;
    u_xlat2.x = u_xlat1.z * 0.0900000036 + u_xlat2.x;
    u_xlat2.x = u_xlat3 * u_xlat2.x;
    u_xlat2.x = u_xlat2.x * _WaveStrength;
    u_xlat4 = _Randomness * 0.400000006 + 1.0;
    u_xlat1.x = u_xlat2.x * u_xlat4 + vs_TEXCOORD0.x;
    u_xlat0.x = u_xlat1.x * 9.72999954 + u_xlat0.x;
    u_xlat2.x = u_xlat1.x * 17.2099991 + (-u_xlat0.w);
    u_xlat0.y = vs_TEXCOORD0.y * 3.4000001 + u_xlat2.x;
    u_xlat0.x = vs_TEXCOORD1 * 10.0 + u_xlat0.x;
    u_xlat0.xy = sin(u_xlat0.xy);
    u_xlat0.x = u_xlat0.y * 0.400000006 + u_xlat0.x;
    u_xlat0.x = u_xlat0.x * _VerticalStrength;
    u_xlat1.y = u_xlat0.x * _Randomness + vs_TEXCOORD0.y;
    u_xlat16_0 = texture(_MainTex, u_xlat1.xy);
    SV_Target0 = u_xlat16_0 * vs_COLOR0;
    return;
}
